CREATE TABLE "gitea_issues" (
    "id" INT8 NOT NULL,
    "repo_id" INT8 NOT NULL,
    "index" INT8 NOT NULL,
    "poster_id" INT8 NOT NULL,
    "original_author" STRING,
    "original_author_id" INT8,
    "name" STRING NOT NULL,
    "content" STRING NOT NULL,
    "content_version" INT4 NOT NULL,
    "milestone_id" INT8,
    "priority" INT4 NOT NULL,
    "is_closed" BOOL NOT NULL,
    "is_pull" BOOL NOT NULL,
    "ref" STRING,
    "deadline_unix" INT8,
    "created_unix" INT8 NOT NULL,
    "updated_unix" INT8 NOT NULL,
    "closed_unix" INT8,
    "is_locked" BOOL NOT NULL,
    "time_estimate" INT8 NOT NULL,
    PRIMARY KEY ("id")
);





